#include <stdio.h>

int main(void) {
    int n, pesos[1024];
    scanf("%d", &n);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &pesos[i]);
        total += pesos[i];
    }
    if (n > 0) total += n - 1;
    printf("%lld\n", total);
    return 0;
}

