rust.reference:
use std::io::{self, Read};

fn main() {
    let mut entrada = String::new();
    io::stdin().read_to_string(&mut entrada).unwrap();
    let mut partes = entrada.split_whitespace();
    let n: usize = partes.next().unwrap().parse().unwrap();
    let mut pesos: Vec<i64> = Vec::new();
    for _ in 0..n {
        pesos.push(partes.next().unwrap().parse().unwrap());
    }
    let total: i64 = pesos.iter().sum::<i64>() + if n > 0 { n as i64 - 1 } else { 0 };
    println!("{}", total);
}
